    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (!Model.IsValid())
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@using sv_8d98ed27c602473db90f0f578c3ddc9d.Models
@namespace sv_8d98ed27c602473db90f0f578c3ddc9d.Components.Application

<div>
    <h4 class="mb-3">Work History</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="@(index + 1)"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-primary btn-sm mb-4" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between mt-2">
        <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? ErrorMessage;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1) Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (!Entries.All(e => e.IsValid()))
        {
            ErrorMessage = "Please fill in company name and job title for all positions.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_8d98ed27c602473db90f0f578c3ddc9d.Models
@namespace sv_8d98ed27c602473db90f0f578c3ddc9d.Components.Application

<div>
    <h4 class="mb-3">References</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="@(index + 1)"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-outline-primary btn-sm mb-4" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between mt-2">
        <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3) References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2) References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (References.Count < 2 || !References.All(r => r.IsValid()))
        {
            ErrorMessage = "Please fill in all fields for at least 2 references.";
            return;
        }
        await OnNext.InvokeAsync();
    }
}

@namespace sv_8d98ed27c602473db90f0f578c3ddc9d.Components.Application

<div>
    <h4 class="mb-3">Cover Letter</h4>

    <div class="mb-2">
        <textarea class="form-control" rows="12" maxlength="@MaxLength"
                  @bind="CoverLetter" @bind:event="oninput"
                  placeholder="Write your cover letter here…"></textarea>
    </div>
    <div class="text-end text-muted small mb-4">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private async Task HandleNext()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
        await OnNext.InvokeAsync();
    }
}

@using sv_8d98ed27c602473db90f0f578c3ddc9d.Models
@namespace sv_8d98ed27c602473db90f0f578c3ddc9d.Components.Application

<div>
    <h4 class="mb-3">Review & Submit</h4>

    @if (IsSubmitted)
    {
        <div class="alert alert-success text-center py-4">
            <h5 class="mb-2">🎉 Application Submitted!</h5>
            <p class="mb-0">Your application ID is <strong>#@ApplicationId</strong>. We'll be in touch!</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <!-- Personal Info -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6"><small class="text-muted">Name</small><div>@Personal.FullName</div></div>
                    <div class="col-md-6"><small class="text-muted">Email</small><div>@Personal.Email</div></div>
                    <div class="col-md-6 mt-2"><small class="text-muted">Phone</small><div>@Personal.Phone</div></div>
                    <div class="col-md-6 mt-2"><small class="text-muted">Address</small><div>@Personal.Address</div></div>
                </div>
            </div>
        </div>

        <!-- Work History -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-3 pb-3 border-bottom last-child-no-border">
                        <div class="fw-semibold">@entry.Title at @entry.Company</div>
                        <div class="text-muted small">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <div class="mt-1 small">@entry.Description</div>
                        }
                    </div>
                }
            </div>
        </div>

        <!-- References -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span><br />
                        <small>@r.Email · @r.Phone</small>
                    </div>
                }
            </div>
        </div>

        <!-- Cover Letter -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space:pre-wrap;">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">← Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitting { get; set; }
    public bool IsSubmitted { get; set; }
    public int? ApplicationId { get; set; }
    public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    public void ShowConfirmation(int id)
    {
        ApplicationId = id;
        IsSubmitted = true;
        StateHasChanged();
    }
}

