<nav class="d-flex justify-content-between align-items-center mb-4 px-2">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var isActive = step == CurrentStep;
        var isCompleted = step < CurrentStep;
        var isFuture = step > CurrentStep;

        <div class="d-flex align-items-center">
            <button class="btn btn-sm rounded-circle @StepCircleClass(isActive, isCompleted) d-flex align-items-center justify-content-center"
                    style="width:32px;height:32px;font-size:0.85rem;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(step)">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </button>
            <span class="ms-1 small @StepTextClass(isActive, isCompleted, isFuture)">@StepNames[step]</span>
        </div>

        @if (i < StepNames.Length - 1)
        {
            <div class="flex-grow-1 mx-2" style="height:2px;background:@(isCompleted ? "#198754" : "#dee2e6");min-width:20px;"></div>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string StepCircleClass(bool active, bool completed)
    {
        if (active) return "btn-primary";
        if (completed) return "btn-success";
        return "btn-outline-secondary";
    }

    private string StepTextClass(bool active, bool completed, bool future)
    {
        if (active) return "fw-bold text-primary";
        if (completed) return "text-success";
        return "text-muted";
    }
}
