@page "/apply"
@using sv_8d98ed27c602473db90f0f578c3ddc9d.Components.Application
@using sv_8d98ed27c602473db90f0f578c3ddc9d.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width:800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personal"
                              ApplicationService="ApplicationService"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnBack="PrevStep"
                             OnNext="NextStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnBack="PrevStep"
                            OnNext="NextStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="val => _coverLetter = val"
                             OnBack="PrevStep"
                             OnNext="NextStep" />
            break;
        case 4:
            <ReviewStep @ref="_reviewStep"
                        Personal="_personal"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnBack="PrevStep"
                        OnEdit="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfoModel _personal = new();
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";
    private ReviewStep? _reviewStep;

    private void NextStep()
    {
        if (_currentStep < 4) _currentStep++;
    }

    private void PrevStep()
    {
        if (_currentStep > 0) _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 0 && step < _currentStep) _currentStep = step;
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personal.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter
        );

        var id = await ApplicationService.SubmitApplicationAsync(application);
        _reviewStep?.ShowConfirmation(id);
    }
}

